WITH roles AS(SELECT r.* FROM pg_roles r WHERE rolname IN('yunipals_unified_api','yunipals_unified_collector','yunipals_unified_read_cache','yunipals_unified_islands_api','yunipals_islands_staking','yunipals_unified_support','yunipals')OR(rolname LIKE 'yunipals%'AND(rolname LIKE '%metadata%'OR rolname LIKE '%native_meta%'))),ns AS(SELECT * FROM pg_namespace WHERE nspname IN('unified_ypal_20261023_v1','yunipals_ownership_4e77f52b_v4','yunipals_ownership_4e77f52b_v5','unified_shadow_20261020_7e7375b0','yunipals_ownership_35cdcb32_v3','yunipals_ownership_35cdcb32_v4','yunipals_indexer_control','metadata','metadata_projection','metadata_source','yunipals_base_islands_v1','yunipals_boosters_launch_v1','yunipals_boosters_ypal_v1')OR nspname LIKE '%solana%'),rels AS(SELECT c.*,n.nspname FROM pg_class c JOIN ns n ON n.oid=c.relnamespace WHERE c.relkind IN('r','p','v','m','f','S')),funcs AS(SELECT p.*,n.nspname FROM pg_proc p JOIN ns n ON n.oid=p.pronamespace WHERE n.nspname LIKE 'yunipals_ownership_%'),
all_edges AS(
 SELECT 'schema'::text kind,n.oid::text object,n.nspname object_name,a.grantee,a.grantor,a.privilege_type privilege,a.is_grantable grantable,NULL::integer column_number FROM pg_namespace n CROSS JOIN LATERAL aclexplode(n.nspacl)a WHERE a.grantee IN(SELECT oid FROM roles)
 UNION ALL SELECT 'relation',c.oid::text,n.nspname||'.'||c.relname,a.grantee,a.grantor,a.privilege_type,a.is_grantable,NULL FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL aclexplode(c.relacl)a WHERE a.grantee IN(SELECT oid FROM roles)
 UNION ALL SELECT 'function',p.oid::text,n.nspname||'.'||p.proname||'('||oidvectortypes(p.proargtypes)||')',a.grantee,a.grantor,a.privilege_type,a.is_grantable,NULL FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace CROSS JOIN LATERAL aclexplode(p.proacl)a WHERE a.grantee IN(SELECT oid FROM roles)
 UNION ALL SELECT 'database',d.oid::text,d.datname,a.grantee,a.grantor,a.privilege_type,a.is_grantable,NULL FROM pg_database d CROSS JOIN LATERAL aclexplode(d.datacl)a WHERE a.grantee IN(SELECT oid FROM roles)
 UNION ALL SELECT 'column',c.oid::text,n.nspname||'.'||c.relname,a.grantee,a.grantor,a.privilege_type,a.is_grantable,att.attnum FROM pg_attribute att JOIN pg_class c ON c.oid=att.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL aclexplode(att.attacl)a WHERE a.grantee IN(SELECT oid FROM roles)AND att.attnum>0 AND NOT att.attisdropped
 UNION ALL SELECT 'default',d.oid::text,COALESCE(n.nspname,'*')||':'||d.defaclobjtype::text,a.grantee,a.grantor,a.privilege_type,a.is_grantable,NULL FROM pg_default_acl d LEFT JOIN pg_namespace n ON n.oid=d.defaclnamespace CROSS JOIN LATERAL aclexplode(d.defaclacl)a WHERE a.grantee IN(SELECT oid FROM roles))
SELECT jsonb_build_object('database',current_database(),'databaseOid',(SELECT oid::text FROM pg_database WHERE datname=current_database()),'currentUser',current_user,'sessionUser',session_user,'socket',inet_client_addr() IS NULL,'port',current_setting('port'),
'roles',(SELECT jsonb_agg(jsonb_build_object('name',r.rolname,'oid',r.oid::text,'login',r.rolcanlogin,'inherit',r.rolinherit,'super',r.rolsuper,'createRole',r.rolcreaterole,'createDatabase',r.rolcreatedb,'replication',r.rolreplication,'bypassRls',r.rolbypassrls,'limit',r.rolconnlimit,'memberships',(SELECT COALESCE(jsonb_agg(jsonb_build_object('roleOid',m.roleid::text,'roleName',x.rolname,'admin',m.admin_option)ORDER BY m.roleid),'[]'::jsonb)FROM pg_auth_members m JOIN pg_roles x ON x.oid=m.roleid WHERE m.member=r.oid))ORDER BY r.rolname)FROM roles r),
'schemas',(SELECT jsonb_agg(jsonb_build_object('name',nspname,'oid',oid::text,'owner',nspowner::text,'acl',COALESCE(nspacl,acldefault('n',nspowner))::text)ORDER BY nspname)FROM ns),
'relations',(SELECT jsonb_agg(jsonb_build_object('schema',nspname,'name',relname,'oid',oid::text,'owner',relowner::text,'kind',relkind,'acl',COALESCE(relacl,acldefault(CASE WHEN relkind='S' THEN 'S'::"char" ELSE 'r'::"char" END,relowner))::text,'definitionMd5',CASE WHEN relkind='v'THEN md5(pg_get_viewdef(oid,true))END)ORDER BY nspname,relname)FROM rels),
'functions',(SELECT jsonb_agg(jsonb_build_object('schema',nspname,'name',proname,'arguments',oidvectortypes(proargtypes),'oid',oid::text,'owner',proowner::text,'definer',prosecdef,'config',proconfig,'acl',COALESCE(proacl,acldefault('f',proowner))::text,'definitionMd5',md5(pg_get_functiondef(oid)))ORDER BY nspname,proname)FROM funcs),
'effective',(SELECT jsonb_agg(jsonb_build_object('role',r.rolname,'schemas',(SELECT jsonb_object_agg(nspname,jsonb_build_object('usage',has_schema_privilege(r.oid,n.oid,'USAGE'),'create',has_schema_privilege(r.oid,n.oid,'CREATE')))FROM ns n),'relations',(SELECT jsonb_object_agg(nspname||'.'||relname,jsonb_build_object('select',CASE WHEN relkind='S'THEN has_sequence_privilege(r.oid,c.oid,'SELECT')ELSE has_table_privilege(r.oid,c.oid,'SELECT')END,'writes',CASE WHEN relkind='S'THEN has_sequence_privilege(r.oid,c.oid,'USAGE,UPDATE')ELSE (has_table_privilege(r.oid,c.oid,'INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')OR(c.nspname='yunipals_ownership_4e77f52b_v5'AND has_any_column_privilege(r.oid,c.oid,'INSERT,UPDATE,REFERENCES')))END))FROM rels c),'functions',(SELECT jsonb_object_agg(nspname||'.'||proname||'('||oidvectortypes(p.proargtypes)||')',has_function_privilege(r.oid,p.oid,'EXECUTE'))FROM funcs p))ORDER BY r.rolname)FROM roles r),
'directRoleEdges',(SELECT COALESCE(jsonb_agg(to_jsonb(e)ORDER BY grantee,kind,object,column_number,grantor,privilege),'[]'::jsonb)FROM all_edges e),
'targetEdges',(SELECT COALESCE(jsonb_agg(to_jsonb(e)ORDER BY kind,object,grantee,grantor,privilege),'[]'::jsonb)FROM(
 SELECT 'schema'::text kind,n.oid::text object,n.nspname object_name,a.grantee::text grantee,a.grantor::text grantor,a.privilege_type privilege,a.is_grantable grantable FROM pg_namespace n CROSS JOIN LATERAL aclexplode(COALESCE(n.nspacl,acldefault('n',n.nspowner)))a WHERE n.nspname IN('unified_ypal_20261023_v1','yunipals_ownership_4e77f52b_v4','yunipals_ownership_4e77f52b_v5','yunipals_indexer_control')
 UNION ALL SELECT 'relation',c.oid::text,n.nspname||'.'||c.relname,a.grantee::text,a.grantor::text,a.privilege_type,a.is_grantable FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL aclexplode(COALESCE(c.relacl,acldefault('r',c.relowner)))a WHERE n.nspname IN('unified_ypal_20261023_v1','yunipals_ownership_4e77f52b_v4','yunipals_ownership_4e77f52b_v5','yunipals_indexer_control')AND c.relkind IN('r','p','v','m','f')
 UNION ALL SELECT 'function',p.oid::text,n.nspname||'.'||p.proname||'('||oidvectortypes(p.proargtypes)||')',a.grantee::text,a.grantor::text,a.privilege_type,a.is_grantable FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace CROSS JOIN LATERAL aclexplode(COALESCE(p.proacl,acldefault('f',p.proowner)))a WHERE n.nspname IN('yunipals_ownership_4e77f52b_v4','yunipals_ownership_4e77f52b_v5')
 )e),
'activeRelease',COALESCE((SELECT jsonb_agg(to_jsonb(a)ORDER BY name)FROM yunipals_indexer_control.active_release a),'[]'::jsonb),'nativeMetadataAdoptions',(SELECT count(*)FROM metadata_source.native_base_metadata_state WHERE release_id='0x4e77f52be3e0daa7075a22afe03fbeb7352daee788265ff69fe5c9ec2cf5c1f3'),'nativeMetadataExplicitRoles',(SELECT COALESCE(jsonb_agg(DISTINCT jsonb_build_object('role',COALESCE(r.rolname,'PUBLIC'),'oid',a.grantee::text,'object',n.nspname||'.'||c.relname,'privilege',a.privilege_type,'grantor',a.grantor::text)),'[]'::jsonb)FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL aclexplode(COALESCE(c.relacl,acldefault('r',c.relowner)))a LEFT JOIN pg_roles r ON r.oid=a.grantee WHERE n.nspname='metadata_source'AND c.relname IN('native_base_metadata_state','chain_metadata_scan')))